-- 2907 🏋️ Exercises from the book "ren-meulensteen-man-utd-methods-of-success-vol-2-full-season-plan-training-sessi" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'ren-meulensteen-man-utd-methods-of-success-vol-2-full-season-plan-training-sessi');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Diamond passing tempo circuit with recovery', 'passing_unopposed', 'unopposed', 'in_possession', 25, 25, 'Pre-Season Morning Session: 2. Technical Passing Tempo and Active Recovery Diamond Circuit', 'Meulensteen (Man Utd)', 'Passing quality, body shape and timing of movement at high tempo, with active recovery between sets.', 'A 12 metre diamond with players stationed at the points (A to H); groups of 10 with 2 balls.', 'Players play the set passing pattern round the diamond and follow their pass to the next station (A>B>C>...>H>A). Two sets, each of two full rounds going right then left.', 'Between sets, pairs with one ball do active recovery: 2 rounds of 8 headers, passes while one partner backpedals, come to the ball then retreat and head a partner''s throw, and let the ball run through the legs, spin and turn.', 'Switch direction (right then left).', 'Body shape open to the next pass, timing of the run, keep the tempo high.', 'groups of 10', 10, 10, '12 metre diamond', 12.0, 12.0, 10.0, false, false, false, NULL, 10),
  ('3v3v3 transition wave game', 'transition', 'opposed', 'to_attack', 26, 26, 'Pre-Season Morning Session: 3. 3-Team 3v3v3 (+GKs) Transition Wave Game', 'Meulensteen (Man Utd)', 'Attack quickly to score and, on winning the ball, break immediately the other way.', '60 x 40 yard pitch split into 3 zones with a large goal and GK at each end; three teams of 3, one waiting at the far end.', 'Reds attack 3v3 against blues in the middle and attacking zone and try to score fast. If blues win the ball they counter 3v3 towards the opposite goal against the waiting whites, and the wave continues.', 'Defenders must start in their defensive zone before they engage.', NULL, 'Score quickly; immediate switch to attack on regaining the ball.', '3v3v3 + 2 GKs', 11, 11, '60 x 40 yards', 54.8, 36.6, 10.0, true, true, true, NULL, 20),
  ('Pair serve and chest control recovery', 'technical', 'unopposed', NULL, 26, 26, 'Pre-Season Morning Session: 4. Active Recovery Ball Work', 'Meulensteen (Man Utd)', 'Active recovery with simple receiving work between high-intensity games.', 'Pairs with one ball.', 'One partner serves, the other controls on the chest, moves away, then returns the ball in two touches.', '2 touches.', NULL, NULL, 'pairs', 2, NULL, NULL, NULL, NULL, 4.0, false, false, false, NULL, 30),
  ('3v3v3 plus two forwards overload wave', 'transition', 'overload', 'in_possession', 27, 27, 'Pre-Season Morning Session: 5. 3-Team 3v3v3 (+2) +GKs Overload Transition Wave Game', 'Meulensteen (Man Utd)', 'Use a 5v3 overload to finish attacks quickly, and counter at once after a regain.', 'Same 60 x 40 yard pitch in 3 zones, but 4 small goals (2 at each end); three teams of 3 plus two neutral forwards F1 and F2.', 'Reds attack blues 3v3 in the middle and attacking zone, helped by F1 and F2 linking play, making 5v3. If blues win it they attack 3v3 (+2 forwards) towards the other end against the waiting whites.', 'Defenders must start in their defensive zone before engaging; the two forwards play for the team in possession.', 'Builds on the 3v3v3 wave game.', 'Use the forwards to link play; exploit the overload quickly.', '3v3v3 + 2 neutrals + GKs', 11, 13, '60 x 40 yards', 54.8, 36.6, 10.0, true, true, true, NULL, 40),
  ('Group juggling recovery', 'technical', 'unopposed', NULL, 27, 27, 'Pre-Season Morning Session: 6. Active Recovery Ball Work', 'Meulensteen (Man Utd)', 'Active recovery with ball control between games.', '4 groups of 5, one ball per group.', 'Groups keep the ball up, first in a two-touch sequence, then one touch.', '2-touch then 1-touch juggling.', '2 touch to 1 touch.', NULL, '4 groups of 5', 5, 20, NULL, NULL, NULL, 4.0, false, false, false, NULL, 50),
  ('6v6v6 forward link-play wave game', 'transition', 'opposed', 'in_possession', 28, 28, 'Pre-Season Morning Session: 7. 3-Team 6v6 (+2) +GKs Forward Link Play Transition Wave Game', 'Meulensteen (Man Utd)', 'Play forward into a target striker to build attacks, and counter quickly after winning the ball.', 'Narrow half pitch with 2 large goals and GKs; three teams of 6 (two play, one rests) plus a neutral forward in each half.', 'Coach passes to the attacking team, whose first pass must go into the neutral forward (6v6+1). Defenders hold a line 1-3 m in front of the box. Attackers get two balls in a row; if they lose the second, defenders counter towards the other end and the resting team steps in to defend.', 'First pass must be to the forward; attacking team gets 2 consecutive balls.', NULL, 'Defensive line set just outside the box; quick restart and immediate counter.', '6v6v6 + 2 neutral forwards + 2 GKs', 22, 22, 'narrow half pitch', NULL, NULL, 20.0, true, true, true, NULL, 60),
  ('Threes passing: one-two, third man, long', 'passing_unopposed', 'unopposed', 'in_possession', 30, 30, 'Pre-Season Afternoon Session: warm-up', 'Meulensteen (Man Utd)', 'Warm up with combination passing, third-man runs and long passing.', 'Half pitch, 6 groups of 3 players (A, B, C).', 'Groups play one-two combinations rotating A>B>C, then a third-man run pattern repeated three times before changing roles, then long passes over 20-30 yards.', NULL, 'One-two, then third man running, then long passing.', NULL, '6 groups of 3', 3, 18, 'half pitch', NULL, NULL, 10.0, false, false, false, NULL, 70),
  ('9v9 full pitch three-game sequence', 'conditioned_game', 'opposed', 'in_possession', 30, 30, 'Pre-Season Afternoon Session: 9v9 +3 GKs Game on Full Pitch', 'Meulensteen (Man Utd)', 'Possession then shooting from distance and close range in a full-pitch game.', 'Full pitch, 9v9 with 3 GKs: one in each box and one in the centre circle (with a third goal on the halfway line for games 2-3).', 'Game 1 (3 min): keep possession using the 3 GKs, no entering boxes or centre circle. Game 2 (3 min): 3 goals, still no entry to boxes or circle, score from outside. Game 3 (3 min): as game 2 but goals must be scored from inside the box or circle.', '3 x 3 min, 2 sets; tempo runs (30 m with 30 s rest, 8 reps) between sets.', 'Possession -> score from outside -> score from inside.', NULL, '9v9 + 3 GKs', 21, 21, 'full pitch', NULL, NULL, 18.0, true, true, true, NULL, 80),
  ('Exercise bikes and injury prevention', 'warm_up', 'unopposed', NULL, 67, 67, 'Session 1: 1. Exercise Bikes + Injury Prevention Exercises', 'Meulensteen (Man Utd)', 'Physical activation and injury prevention at the start of every session.', 'Exercise bikes plus an injury-prevention routine; no diagram or detail given.', 'Players spin on bikes then do injury-prevention exercises before ball work (repeated as item 1 in every session).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15.0, false, false, false, NULL, 90),
  ('8v2 one-touch rondo boxes', 'rondo', 'overload', 'in_possession', 67, 67, 'Session 1: 2. 8v2 Boxes (1 Touch Rondos)', 'Meulensteen (Man Utd)', 'Quick one-touch circulation, awareness and splitting a two-man press.', 'Several 8 x 8 yard boxes, each with 8 players on the outside and 2 defenders inside (groups of 10).', 'The 8 outside players keep the ball away from the 2 inside defenders, who work together to cut angles and win it.', '1 touch; no return pass to the player who just passed to you.', NULL, 'Scan and move feet early; split the defenders or play round them quickly; choose short or long; disguise passes.', '8v2 (groups of 10)', 10, NULL, '8 x 8 yards', 7.3, 7.3, 10.0, false, false, false, NULL, 100),
  ('Full-pitch switching aerobic passing pattern', 'passing_unopposed', 'unopposed', 'in_possession', 68, 68, 'Session 1: 3. Switching Play Aerobic Passing Pattern Routine', 'Meulensteen (Man Utd)', 'Passing weight, timing and clean body shape for switches while building aerobic load.', 'Full pitch, players at positions A-H with poles and a mannequin; two identical patterns run at once from opposite ends.', 'A dribbles and one-twos with B, passes via C to D; D one-twos with E and switches to G; G give-and-goes around a pole with F, then feeds H who drives past the mannequin and dribbles back to the start. Each player moves on one position; next ball starts when D switches.', NULL, NULL, 'Weight of pass and timing; clean switching technique; be ready for the next action.', 'Full squad in 2 mirrored groups', NULL, NULL, 'Full pitch', NULL, NULL, 10.0, false, false, true, NULL, 110),
  ('6v6 (+4) centre back end zone build-up', 'possession', 'overload', 'in_possession', 69, 69, 'Session 1: 4. 6v6 (+4) End Zone Centre Back Build-Up Possession Game', 'Meulensteen (Man Utd)', 'Positional discipline and forward passing from the back line in build-up.', '38 x 40 area with an end zone at each end holding 2 neutral centre backs; 6v6 in the middle.', 'Neutral CBs start play and pass forward into the middle; teams try to move the ball from one end zone to the other. Winning team gets the same aim.', NULL, NULL, 'Keep correct distances from the CBs to make passing lanes; spot the moment to play forward; keep structure while circulating.', '6v6 (+4)', 16, 16, '38 x 40', 34.7, 36.6, 10.0, false, false, true, NULL, 120),
  ('8v8 (+4) centre back switch build-up game', 'possession', 'overload', 'in_possession', 70, 70, 'Session 1: 5. 8v8 (+4) End Zone Centre Back Build-Up Possession Game', 'Meulensteen (Man Utd)', 'Circulating across the back line and switching under pressure before playing forward.', 'Larger area, 8v8 in the middle with 2 neutral centre backs in each end zone.', 'Play end zone to end zone. When a CB receives he must pass across to the other CB before the ball can go back into the main area. Possession change keeps the same aim.', '1-2 touches; CB to CB pass required before re-entering the main area.', NULL, 'Quick accurate CB-CB passes; patience before playing in; tempo and spacing.', '8v8 (+4)', 20, 20, NULL, NULL, NULL, 10.0, false, false, true, NULL, 130),
  ('8v8 (+1) 3-zone build-up to overload', 'phase_of_play', 'overload', 'in_possession', 71, 71, 'Session 1: 6. 8v8 (+1) +GKs Build-Up to Overload Attack 3-Zone Game', 'Meulensteen (Man Utd)', 'Building from the keeper to create quick overloads and chances in the attacking half.', 'Box-to-box area split into defensive, middle and attacking zones; 8v8 plus a neutral (Rooney role) and 2 GKs.', 'Start from the GK; the neutral drops to make 5v4 in the defensive zone. When the ball reaches the middle zone, the passer and the neutral push into the attacking zone to create 6v4 and finish quickly.', 'An attacker may drop into the middle zone to support.', NULL, 'Play out from the GK with speed and composure; support quickly into the attacking zone; decisive quick circulation.', '8v8 (+1) +GKs', 19, 19, 'Box to box', NULL, NULL, 10.0, true, true, true, NULL, 140),
  ('9v9 build-up to two goals vs counter', 'small_sided_game', 'opposed', 'in_possession', 72, 72, 'Session 1: 7. 9v9 (+3 GKs) Build-Up to Score in Two Goals vs Counter Attack Game', 'Meulensteen (Man Utd)', 'Calm build-up under pressure, use of width and protection against counters.', 'Reds 9 + GK defend one goal; blues 9 + 2 GKs defend two goals on the far line (score zone).', 'Reds build from their GK in 1-2 touches and can score in either of the two goals; blues who win the ball counter with no limits. Reds who regain switch quickly and score.', 'Reds 1-2 touches; blues unlimited.', NULL, 'Quick 1-2 touch circulation; support at different heights to protect against counters; react instantly to regains and switch wide.', '9v9 +3 GKs', 21, 21, NULL, NULL, NULL, 20.0, true, true, true, NULL, 150),
  ('Reactive passing and receiving rotation warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 74, 74, 'Session 2: 3. Reactive Passing and Receiving Rotation Warm-Up', 'Meulensteen (Man Utd)', 'Sharp receiving and returning with a feeder while moving.', '6 players inside a central area of poles, 6 feeders around the outside with a ball each.', 'Inside players spring out to a feeder, receive and return, then move back into the middle and on to another feeder; continuous. After about 30 seconds (5 passes) roles swap.', NULL, 'Variations: firm pass and return; receive and switch places with the feeder; short sharp volleys.', NULL, '12 (6 in, 6 out)', 12, 12, NULL, NULL, NULL, 10.0, false, false, false, NULL, 160),
  ('5v5 (+4) possession with end zones', 'positional_game', 'overload', 'in_possession', 75, 75, 'Session 2: 4. 5v5 (+4) Possession Games with End Zones', 'Meulensteen (Man Utd)', 'Use overloads, quick decisions and early forward passes.', 'Part 1: 5v5 +4 in a 24 yard square. Part 2: 20 x 28 area with an end zone at each end holding 2 neutrals.', 'Part 1 (6 min): keep-ball with the 4 neutrals. Part 2 (6 min): keep the ball with the overload and move it end to end via the neutral end players.', 'Start 1-2 touch, then 1 touch in part 1; part 2 starts 1-2 touch then unlimited.', 'Part 1 square keep-ball progresses to the directional end-zone version.', 'Make overloads around the ball for clear options; spot when to play forward early without forcing it.', '5v5 (+4)', 14, 14, '24 x 24 yards / 20 x 28', 25.6, 18.3, 12.0, false, false, true, NULL, 170),
  ('6v6 (+1) +6 directional possession, outside targets', 'positional_game', 'overload', 'to_attack', 76, 76, 'Session 2: 5. 6v6 (+1) +6 Directional Possession Game with Outside Target Players', 'Meulensteen (Man Utd)', 'Decision-making in possession under directional pressure and playing forward early.', '40 x 40 split by a halfway line; two teams of 6 start in opposite halves, a joker inside and a third team of 6 as outside target players.', 'Coach serves to one team; the other crosses over to press. Possession team scores by getting into the attacking half then passing to an outside player; defenders score by intercepting and passing straight to an outside player. Rotate roles after a set time.', '1 point for each scoring pass.', NULL, 'Progress with control; give angles ahead of the ball; know when to secure and when to penetrate; react instantly to regains.', '6v6 (+1) +6', 19, 19, '40 x 40', 36.6, 36.6, 10.0, false, false, true, NULL, 180),
  ('10v10 directional possession, receiving end zones', 'positional_game', 'opposed', 'in_possession', 77, 77, 'Session 2: 6. 10v10 Directional Possession Game with Receiving End Zones', 'Meulensteen (Man Utd)', 'Purposeful possession and movement to receive in end zones.', '48 x 50 area with halfway line and an end zone at each end.', 'Teams keep the ball and score by passing to a teammate who receives inside the end zone they attack.', 'Can only score once the ball has crossed halfway (no long balls).', NULL, 'Circulate to create space before penetrating; stretch the opponent and step up together; draw pressure to free teammates; accelerate once beyond halfway.', '10v10', 20, 20, '48 x 50', 43.9, 45.7, 10.0, false, false, true, NULL, 190),
  ('11v11 build-up, rotations and attack through gates', 'conditioned_game', 'opposed', 'in_possession', 78, 78, 'Session 2: 7. Tactical Build-Up, Rotations, Switch Play, and Attack Through Gates Game', 'Meulensteen (Man Utd)', 'Build-up, rotations, combinations and switches to break through and attack the goal.', 'Reds in 4-2-3-1 with GK vs blues in 4-4-2; 4 yellow pole gates in the corners and 2 red gates centrally across the pitch.', 'Red GK starts, CBs drop beside him to receive. Reds build up and rotate to play through one of the gates, then attack the blue goal. Blues winning it have the same aim; restart via the middle zone or blue GK.', 'Defending rules can be varied: no defending once through a gate; 1 CB may defend; 2 CBs; all 4 defenders.', 'Progress the defending rules from none to all 4 defenders.', NULL, '11v11', 22, 22, NULL, NULL, NULL, 20.0, true, true, true, NULL, 200),
  ('Centre circle and outside one-two passing', 'passing_unopposed', 'unopposed', 'in_possession', 80, 80, 'Session 3: 3. Centre Circle and Outside One-Two Combination Passing Warm-Up', 'Meulensteen (Man Utd)', 'One-two combinations and timed runs as a passing warm-up.', 'Group 1 in and around the centre circle with a middle player; group 2 around a large outer rectangle with mannequins, starting from opposite corners.', 'Group 1: one-two with the middle player, pass out to an outside player and take his place; next player passes direct out. Group 2: two balls run at once round the outside with a series of one-twos; players follow their pass.', NULL, NULL, 'Time the run; follow your pass.', '2 groups', NULL, NULL, NULL, NULL, NULL, 6.0, false, false, false, NULL, 210),
  ('4v4 (+2) switching possession with wide neutrals', 'possession', 'overload', 'in_possession', 81, 81, 'Session 3: 4. 4v4 (+2) Switching Play Possession Game with Wide Support Players', 'Meulensteen (Man Utd)', 'Keeping the ball with an emphasis on switching across a short, wide area.', 'Short wide area with a central zone and two wide zones; 4v4 centrally plus a yellow neutral in each wide zone.', 'Teams circulate through central and wide areas, using the wide neutrals to overload and switch play.', 'Central players max 3 touches, wide players 2; 2 x 3 minute blocks.', NULL, 'Use width and depth to open switching lanes; move early to support on both sides; control tempo - when to circulate, when to switch.', '4v4 (+2)', 10, 10, NULL, NULL, NULL, 6.0, false, false, false, NULL, 220),
  ('3-ball switch play and through-lines finishing', 'combination', 'passive', 'in_possession', 82, 84, 'Session 3: 5. 3-Ball Switch Play and Play Through the Lines Finishing Combinations', 'Meulensteen (Man Utd)', 'Rehearsed switching, crossing and through-the-lines combinations ending in finishes.', 'Half pitch with GK, 2 CBs, 2 full backs, 2 central mids, 2 forwards; poles in midfield; coach with balls at centre.', 'Ball 1: CB receives from GK, diagonal to full back, inside to CM who switches to the far full back, who dribbles and crosses for 2 timed forward runs. Ball 2: coach feeds CM, who plays into a forward to turn on the half-turn and shoot. Ball 3: coach plays to the other forward and a 3v2 attack goes against the 2 CBs who now defend.', NULL, 'Repeat mirrored from the other side.', 'Release full back at speed; weight of switch and timing of runs; box runs go late, arrive fast; read crossing zones; receive half-turned and use different turns; strike with laces/instep; attack at speed in the 3v2.', '11 incl. GK', 11, NULL, 'Half pitch', NULL, NULL, 15.0, true, true, true, NULL, 230),
  ('Switching play, runs in behind, crossing phases', 'phase_of_play', 'opposed', 'in_possession', 85, 85, 'Session 3: 6. Switching Play, Runs in Behind, Crossing and Finishing Phases of Play', 'Meulensteen (Man Utd)', 'Long switches of play and runs behind the back line to cross and finish.', 'Full-width half-plus pitch; attacking team building from GK vs a defending back line and midfield, some midfielders resting.', 'Build up from the GK, play wide then switch to the far side; from there cross into the box for timed runs in behind the defensive line. Midfield pairs rotate in after 2 reps.', NULL, 'Variations: the striker drops and receives on the half-turn then plays the winger; the winger comes inside and the full back overlaps to receive the switch, dribble and cross.', 'Recognise the moment to switch; long switches encouraged; forward runs timed to the switch.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, true, true, true, NULL, 240),
  ('Switching game with wide zones and dribble gates', 'small_sided_game', 'opposed', 'in_possession', 86, 86, 'Session 3: 7. Controlled Possession and Switching Play Game with Wide Zones and Dribble Gates', 'Meulensteen (Man Utd)', 'Controlled possession and fast switches to exploit space wide or finish centrally.', '58 x 32 area with 12 yard wide zones; at each end a small central goal plus 2 pole gates in the corners. 8v8.', 'Switch quickly to exploit a wide zone and dribble through a pole gate (1 goal), or use width to open the middle and score in the small goal (1 goal).', 'Middle zone 1-2 touches with a 1-touch finish; no touch limit in the wide zones.', NULL, 'Switch fast to the wide space; stretch the block before going central; support around the ball and finish with speed.', '8v8', 16, 16, '58 x 32 yards', 53.0, 29.3, 10.0, true, false, true, NULL, 250),
  ('Attacking waves in fours with CM link', 'finishing', 'unopposed', 'in_possession', 88, 88, 'Session 4: 3. Unopposed Attacking Waves in Fours with Central Midfielder Link Play', 'Meulensteen (Man Utd)', 'Breaking lines with forward passes and linking with a central player to finish.', '20 x 32 area with mannequin lines, a central midfielder, 2 small goals and a GK at each end; 3 teams of 4.', 'Part 1 (6 min): 6v6 (+1) +2 end-player keep-ball (not diagrammed). Part 2 (6 min): GK1 starts a wave of 4 reds; after 3+ passes or a link with the CM they pass to GK2, who sets for a runner to finish first time. Then the blues attack from the opposite end.', '1-touch finish; 3 passes or CM link before playing to the GK.', 'Part 1 possession game precedes the waves.', NULL, '12 + CM + 2 GKs', 15, 15, '20 x 32 yards', 29.3, 18.3, 12.0, true, true, true, NULL, 260),
  ('Playing into the forward combination and finish', 'combination', 'unopposed', 'in_possession', 89, 89, 'Session 4: 4. Playing into the Forward Combination and Finishing Pattern', 'Meulensteen (Man Utd)', 'Realistic through-the-lines combination into the striker and finish.', 'Half pitch with mannequins as defenders; CB, CM, LB, LW and 2 forwards plus GK.', 'CB passes to CM who sets back to LB; LB plays forward for the winger running round a mannequin; winger passes short inside to the forward who turns past the mannequin and shoots. Repeat from the other CB (mirrored).', NULL, 'Variation: winger passes to the second forward, who plays in behind for the first forward running into the box.', 'Quality and timing of the pass forward; quick decision to set, spin or turn; move again after passing.', NULL, NULL, NULL, 'Half pitch', NULL, NULL, 10.0, true, true, true, NULL, 270),
  ('6v6 (+4) play through the lines to finish', 'small_sided_game', 'overload', 'in_possession', 90, 90, 'Session 4: 5. 6v6 (+4) +GKs Play Through the Lines Quickly and Support to Finish Game', 'Meulensteen (Man Utd)', 'Forward passing through central lines with speed and supporting runs to finish.', 'Pitch with end zones; each team in a 2-3-1 shape plus GKs and end wall players (e.g. 2 per end).', 'Play forward as fast as possible to the forward or an end wall player; once the ball reaches a wall player the 3 midfielders and forward may enter the end zone to finish.', 'Defenders stay in their half, forward stays in the attacking half, midfielders free; wall players 2 touches.', NULL, 'Positional discipline to open space between lines; spot moments to play forward fast; immediate forward and diagonal support runs.', '6v6 (+4) +GKs', 18, 18, NULL, NULL, NULL, 12.0, true, true, true, NULL, 280),
  ('8(+2)v9 build-up overload through lines', 'phase_of_play', 'overload', 'in_possession', 91, 91, 'Session 4: 6. Build-Up to Overload and Play Through the Lines to Finish Tactical Game', 'Meulensteen (Man Utd)', 'Circulate to shift the opponent, then play forward at the right moment to finish.', 'Half pitch plus 12 yards in 3 zones with 2 pole gates in zone 1; GK outside the area, reds 8 (+2 CBs) vs 9 blues + GK.', 'CBs combine in zone 1 with zone 2 players returning in 1 touch. A CB dribbles through a pole gate to create 6v4 in zone 2, then play forward into zone 3 for a 5v5 (+GK) attack. Blues winning it counter by dribbling through a gate or passing to a yellow CB.', 'Zone 2 players return passes to CBs in 1 touch.', NULL, 'Scan early for pressure and forward options; know when to keep it and when to play through.', '8 (+2) v 9 +GKs', 21, 21, 'Half pitch + 12 yards', NULL, NULL, 20.0, true, true, true, NULL, 290),
  ('One-twos and lay-off passing sequence', 'passing_unopposed', 'unopposed', 'in_possession', 93, 93, 'Session 5: 3. One-Twos and Lay-Off Passing Sequence Warm-Up', 'Meulensteen (Man Utd)', 'Passing rhythm, support angles and coordinated movement.', 'Two mirrored groups across the half pitch at positions A-H.', 'After 5 min of physical warm-up: A passes diagonally to C, who plays short to D; D lays off for B to play forward to E; E sets for F, F passes across to G, who sets for E; E one-twos with H and passes back to the start.', 'Rotate A>B>C>D>E>F>G>H>opposite group.', NULL, NULL, '2 groups', NULL, NULL, 'Half pitch', NULL, NULL, 20.0, false, false, false, NULL, 300),
  ('8v8 (+4) rotational overload with end zone players', 'positional_game', 'overload', 'in_possession', 94, 94, 'Session 5: 4. 8v8 (+4) Rotational Overload Possession Game with End Zone Players', 'Meulensteen (Man Utd)', 'Rotation, scanning and coordinated support to keep the ball under pressure.', '48 x 55 area; 8v8 in the middle and each team has 2 players in the end zones.', 'The team in possession may use all 4 end zone players (12v8). Passing to your own end zone player means you swap places with him; he then passes across to his partner, who plays back in.', 'Pass to own end zone player = swap positions.', NULL, 'Use spare players for constant superiority; rotate immediately after passing; secure support passes under pressure.', '8 (+2) v 8 (+2)', 20, 20, '48 x 55', 43.9, 50.3, 8.0, false, false, true, NULL, 310),
  ('Mannequin combination play through the lines', 'combination', 'unopposed', 'in_possession', 95, 95, 'Session 5: 5. Attacking Combination Play Through the Lines and Finishing Pattern', 'Meulensteen (Man Utd)', 'Realistic combination patterns through lines ending in a finish.', '8 mannequins as defensive and midfield lines; extra GKs or coaches with balls either side of the goal; mirrored pattern on both sides.', 'GK serves A who one-twos with B, then to C; C sets for B to pass to D, who passes to E; E sets for F to break the lines with a pass for H''s run; H one-twos with G, breaks the line and shoots.', 'Rotate A>B>...>H>opposite group.', NULL, 'G attacks space with purpose; control weight and timing of each pass to keep the rhythm.', NULL, NULL, NULL, NULL, NULL, NULL, 15.0, true, true, true, NULL, 320),
  ('8v8 (+1) attacking overloads through 3 zones', 'phase_of_play', 'overload', 'in_possession', 96, 96, 'Session 5: 6. 8v8 (+1) +GKs Attacking Overloads Through the Zones Game', 'Meulensteen (Man Utd)', 'Creating and exploiting attacking overloads in a match-like set-up.', 'Box edge to end of full pitch split into 3 zones; 8v8 plus a joker and 2 large goals with GKs.', 'GK starts. Zone 1 is 4v3 with the joker; play into zone 2 where the joker moves up to make 3v2; then into zone 3 where 2 players push up for a 5v3 to finish quickly.', NULL, NULL, 'Spot and use overloads early and play forward fast once the advantage exists; support to keep momentum.', '8v8 (+1) +GKs', 19, 19, NULL, NULL, NULL, 10.0, true, true, true, NULL, 330),
  ('7v7 (+6) overloads with wide zones and supports', 'small_sided_game', 'overload', 'in_possession', 97, 97, 'Session 5: 7. 7v7 (+6) +GKs Attacking Overloads with Wide Zones and Support Players Game', 'Meulensteen (Man Utd)', 'Quick circulation, wide support and decisive finishing using a big overload.', '7v7 + GKs with 2 yellow neutrals in the wide zones and 4 end players either side of the goals.', 'Team in possession uses neutrals and end players to overload and score. Restarts: GK rolls short to an end player who plays forward; new ball from the GK when it goes out or after a goal.', 'Wide neutrals 2 touches; end players 1 touch; 3 x 5 min then 3 x 4 min.', NULL, 'Go wide early to stretch and overload centrally; combine quickly or switch to find free players.', '7v7 (+6) +GKs', 20, 20, NULL, NULL, NULL, 30.0, true, true, true, NULL, 340),
  ('3-ball combination, crossing and finishing patterns', 'finishing', 'passive', 'in_possession', 99, 99, 'Session 6: 3. 3-Ball Combination Play, Crossing, and Finishing Patterns', 'Meulensteen (Man Utd)', 'Combination play off mannequins, crossing and finishing in three sequences.', 'Attacking half with mannequins outside the box, GK, coach and players at positions A-G on both sides.', 'Ball 1: A one-twos with B who checks off a mannequin, A touches and shoots. Ball 2: C passes to D, who plays wide to E; E plays back to F, G checks off the mannequin to receive from F and shoots. Ball 3: coach plays for G2''s run to cross; B and G make runs to score.', NULL, 'Variation: E > G > F > E > cross. Repeat mirrored on the other side.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15.0, true, true, true, NULL, 350),
  ('4-corner passing, crossing and first-time finishing', 'finishing', 'unopposed', 'in_possession', 100, 101, 'Session 6: 4. 4-Corner Passing, Crossing, and First-Time Finishing', 'Meulensteen (Man Utd)', 'Timed runs, first-time finishing with both feet, and crossing for runners.', '4 equal groups at the 4 corners of a full-length area with goals and GKs at both ends; mannequins in front of the CBs'' area for part 2; 2 balls from opposite corners at once.', 'Part 1: A/D touch forward and pass into the centre for B/C''s timed run to shoot first time. Part 2: A/D dribble past halfway and cross, bending round the mannequins, for B/C to finish first time.', 'Alternate left and right foot; rotate A>B>C>D after each action.', 'Part 1 central pass and finish progresses to part 2 dribble and cross.', 'Shape the body early to finish first time; accuracy and clean contact over power; look up for the runner; cross low and hard behind the mannequins; time the run and finish in 1 touch.', '4 groups + 2 GKs', NULL, NULL, NULL, NULL, NULL, 10.0, true, true, true, NULL, 360),
  ('5v5 plus wide neutrals crossing game', 'small_sided_game', 'overload', 'in_possession', 102, 102, 'Session 6: Practice 5', 'Meulensteen (Man Utd)', 'Getting the ball wide, overloading and crossing with coordinated box movement.', 'Area between two full-size goals with a wide channel on each side; 5v5 plus GKs, one central neutral and four neutrals stationed in the wide channels.', 'The team on the ball uses the central neutral to help work it out to a wide channel; as soon as it goes wide, teammates push up in support and the wide player crosses or pulls it back for timed runs.', 'Wide neutrals stay in their own channels. 2 x 8 minute halves.', NULL, 'Stretch the defence with width before crossing; forwards move as soon as the ball goes wide, giving the winger time; time runs to attack space.', '5v5 (+5) +GKs', 12, 12, NULL, NULL, NULL, 16.0, true, true, true, NULL, 370),
  ('8v8 wide gates to cross and box runs', 'small_sided_game', 'opposed', 'in_possession', 103, 103, 'Session 6: Practice 6', 'Meulensteen (Man Utd)', 'Attacking via wide areas and turning crosses or cut-backs into finishes with decisive runs into the box.', 'Half-plus pitch: one big goal with GK at the attacking end and three pole gates on the edge of an end zone (two wide, one central); two small goals at the other end.', 'The attackers must play or dribble through a gate before entering the attacking zone; wide players aim to go through a wide gate and cross while the others attack the box. Defenders who win it counter into the two small goals.', 'Max 3 touches; finishes must be one touch.', NULL, 'Use the outside gates to open crossing chances; make aggressive, well-timed runs as the ball enters the zone.', '8v8 (+GK)', 17, 17, NULL, NULL, NULL, 10.0, true, true, true, NULL, 380),
  ('9v8 full back wide zone crosses game', 'small_sided_game', 'opposed', 'in_possession', 104, 104, 'Session 6: Practice 7', 'Meulensteen (Man Utd)', 'Releasing full backs into wide zones to cross early, with box runs and second-ball reactions.', 'Large area with marked wide zones on each flank; reds attack one big goal (GK) and start with a pass from their GK, blues defend it and counter into four small goals.', 'Reds build to free a full back into his own wide zone, who crosses for 2-3 runners attacking near post, penalty spot and far post; blues defend the box, win second balls and break into the small goals.', 'Only a full back may receive in the wide zone to cross. 2 x 8 minute halves.', NULL, 'Cross early from both wings with a set-up first touch; 2-3 box runs across the line at full speed; react to second balls; finish quickly.', '9v8 (+GKs)', 19, 19, NULL, NULL, NULL, 16.0, true, true, true, NULL, 390),
  ('Diagonal forward passing combination warm-up', 'passing_unopposed', 'unopposed', 'in_possession', 106, 106, 'Session 7: Practice 3', 'Meulensteen (Man Utd)', 'Passing weight and angles in a forward diagonal combination pattern.', 'Two mirrored circuits of 8 players (16 in all) across half a pitch, using mannequins as markers; stations A to G.', 'A plays a one-two with B then passes forward to C; C sets for G who passes to D; D plays diagonally forward to E, who lays back for F, who releases G running forward; G passes back to the start.', NULL, NULL, 'Weight of pass; angles of support.', '16 players in 2 groups', 16, 16, NULL, NULL, NULL, 8.0, false, false, true, NULL, 400),
  ('10v10 combinations game with wide gates and central goals', 'small_sided_game', 'opposed', 'in_possession', 107, 107, 'Session 7: Practice 4', 'Meulensteen (Man Utd)', 'Quick recognition of forward passing options and central or wide combinations to finish.', 'Pitch split into 6 zones; big goals with GKs in the centre of each end and a pole gate in each of the 4 corners.', 'Teams play 10v10 and score either by dribbling through a wide gate or by scoring in the big goal.', 'Shots on the big goal are one-touch finishes.', NULL, 'Scan early for forward passes; combine with speed through central and wide areas; finish quickly.', '10v10 (+GKs)', 22, 22, NULL, NULL, NULL, 10.0, true, true, true, NULL, 410),
  ('3-ball attacking combination play around the box', 'combination', 'unopposed', 'in_possession', 108, 109, 'Session 7: Practice 5', 'Meulensteen (Man Utd)', 'Position-specific attacking combinations around the penalty area.', 'Team in shape (CB, two DMs, two AMs, wingers, full backs, two forwards) against mannequins representing the opposition back line and midfield, attacking one goal with GK; coach serves extra balls.', 'Ball 1: CB to DM1, one-two with AM1, pass into F1 who either lays back for AM1 to dribble and shoot or turns past the mannequin to finish. Ball 2: CB plays a one-two with DM2 and switches to RB, who combines with RW in behind and crosses for AM1/F1 runs. Ball 3: coach feeds CB, who finds AM2 who releases LW cutting inside to shoot or slip F2 in behind.', NULL, NULL, 'Match tempo with sharp, accurate passing; time supporting runs to arrive free; finish decisively.', NULL, NULL, NULL, NULL, NULL, NULL, 10.0, true, true, true, NULL, 420),
  ('Switching play, overlaps and central combinations', 'phase_of_play', 'passive', 'in_possession', 110, 110, 'Session 7: Practice 6', 'Meulensteen (Man Utd)', 'Shifting the opposition block by circulating quickly, then finishing via overlap crosses or central combinations.', 'Full team in shape starting from the GK, attacking one goal against a defensive line and midfield of mannequins/defenders.', 'Ball 1: GK and centre backs circulate, switch to the winger, who combines with a forward and the overlapping full back who crosses for three forwards attacking the box. Ball 2: play goes into midfield and through the centre for a combination ending in a shot from outside the box or a pass to the full back.', NULL, NULL, 'Circulate quickly to shift the block; coordinate central and wide movements; attack the box with timing and balance.', NULL, NULL, NULL, NULL, NULL, NULL, 20.0, true, true, true, NULL, 430),
  ('8v8 4-zone 3-goal combination game', 'conditioned_game', 'opposed', 'in_possession', 111, 111, 'Session 7: Practice 7', 'Meulensteen (Man Utd)', 'Combination play, linking and decision-making to progress through zones.', 'Full pitch box to box split into 4 equal zones; one team attacks 2 goals, the other attacks 1 goal; 3 GKs.', 'Teams use quick passing, movement and support angles to create local overloads such as 3v2 and then progress into the next zone.', 'No more than 3 players from a team in one zone at a time.', NULL, 'Combine quickly within a zone before progressing; give the ball carrier clear angles; receive on the move.', '8v8 (+3 GKs)', 19, 19, 'Full pitch, box to box', NULL, NULL, 15.0, true, true, true, NULL, 440),
  ('4-goal dribbling and finishing circuit', 'finishing', 'unopposed', NULL, 113, 113, 'Session 8: Practice 3', 'Meulensteen (Man Utd)', 'Building finishing habits and intensity before game-related work.', 'Full pitch with 4 goals placed around it as a circuit, a ball supply at the start.', 'Players dribble the circuit and shoot at each of the 4 goals in turn, then jog back to the start.', NULL, 'Two shots per goal: a teammate behind feeds a second ball for another shot at each goal.', 'Early preparation, clean contact, composure.', NULL, NULL, NULL, 'Full pitch', NULL, NULL, 6.0, true, true, true, NULL, 450),
  ('6v6 link with the forward 3-zone game', 'small_sided_game', 'opposed', 'in_possession', 114, 114, 'Session 8: Practice 4', 'Meulensteen (Man Utd)', 'Finishing more often under pressure by linking quickly with the striker.', '60 x 40 yard pitch with goals and GKs, an end zone at each end where each team''s forward is stationed.', 'Teams play 6v6; an attack can only score after the ball has been played to the forward in the end zone, after which attackers may run freely into that zone.', 'Defenders may not enter the end zones. Must connect with the forward before scoring.', NULL, 'Combine quickly with the forward; make immediate supporting runs; finish under pressure with few touches.', '6v6 (+GKs)', 14, 14, '60 x 40 yards', 54.8, 36.6, 6.0, true, true, true, NULL, 460),
  ('4(+2)v2 wave finishing with overlapping full backs', 'finishing', 'overload', 'in_possession', 115, 115, 'Session 8: Practice 5', 'Meulensteen (Man Utd)', 'High repetition of crossing and box runs against defenders.', 'Two goals with GKs; three groups of 4 (two CMs and two full backs) attack in waves both ways; 2 yellow link players in the middle and 2 blue defenders who defend and rotate.', 'A full back finds a link player, who plays wide for the other full back''s overlap; the 2 CMs cross over in the centre and the full back crosses for the 3 runners to finish, then the 2 defenders go back to defend the other way.', NULL, NULL, 'Deliver early from wide; time runs to near post, central and far post; finish decisively.', '4(+2)v2 +GKs, 3 groups of 4', NULL, NULL, NULL, NULL, NULL, 12.0, true, true, true, NULL, 470),
  ('4-ball varied finishing from crosses, combinations and long passes', 'finishing', 'unopposed', NULL, 116, 116, 'Session 8: Practice 6', 'Meulensteen (Man Utd)', 'Finishing from different types of service.', 'Edge of the box around one goal with GK; players at stations A to E and C1/C2 around the area.', 'Ball 1: GK throws wide to A, who crosses for B''s run. Balls 2a/2b: C1 and C2 dribble to the box edge, swap a pass, get a new ball and shoot. Ball 4: D plays a long pass for E to control, dribble at the box and shoot.', NULL, NULL, 'Adjust body shape early to the service; take a first touch only if needed; accuracy over power.', NULL, NULL, NULL, NULL, NULL, NULL, 6.0, true, true, true, NULL, 480),
  ('Sprint movement finishing with varied service', 'finishing', 'unopposed', NULL, 117, 118, 'Session 8: Practice 7', 'Meulensteen (Man Utd)', 'Quick finishing after repeated sprint actions.', 'Penalty area with mannequins, cones, ground poles and speed rings; coloured target areas in the goal corners; coaches serve from various angles.', 'Part 1: player checks away and back from a mannequin, then runs onto an aerial or ground ball and finishes in max 2 touches, from either side. Part 2: player does quick feet through poles or rings, meets a pass from behind or the side, turns, dribbles past a mannequin and finishes.', 'Max 2 touches in part 1; aim for the coloured corners. 3 x 6 reps.', 'Part 2 swaps the checking run for footwork through ground poles or speed rings.', 'Sprint with intent into the finishing space; quick feet and correct body shape; stay composed after high-speed movement.', NULL, NULL, NULL, NULL, NULL, NULL, 30.0, true, true, true, NULL, 490),
  ('2-ball passing and immediate pressing tree', 'passing_opposed', 'passive', 'to_defend', 120, 120, 'Session 9: Practice 3', 'Meulensteen (Man Utd)', 'Tempo, awareness and closing down the receiver straight after passing.', 'Rectangle of cones with 6 players per group at stations A to F; 2 balls in play starting with A and D.', 'A and D pass to B and E, who play on to C and F; C and F play into the centre for A and D''s movement, who pass for C and F to come round the cone and dribble to their spots. After the second pass the passer presses the receiver quickly.', '1 touch where possible; move after every pass. Rotate A-B-C-D-E-F.', NULL, 'Pass and press at once (''click/clack'').', '6 per group', 6, 6, NULL, NULL, NULL, 10.0, false, false, false, NULL, 500),
  ('3-team possession and pressing with zone switching', 'rondo', 'overload', 'to_defend', 121, 121, 'Session 9: Practice 4', 'Meulensteen (Man Utd)', 'Coordinated pressing and quick recovery runs as play switches between zones.', 'Three equal 7 x 7 yard boxes in a line, three teams of 4.', 'Reds keep the ball 4v2 against two blues in an end box and after 3 passes switch it to the yellows in the far box; the other 2 blues then move over to press there. If blues win it they pass to the free box and swap roles.', '3 passes before switching; team losing the ball becomes the defenders.', NULL, 'Press together at correct distances to close lanes; communicate early on loss or regain.', '3 teams of 4', 12, 12, 'Three 7 x 7 yard boxes', 6.4, 19.2, 10.0, false, false, true, NULL, 510),
  ('6v5 compact defence against through passes', 'defending', 'overload', 'out_of_possession', 122, 122, 'Session 9: Practice 5', 'Meulensteen (Man Utd)', 'Compact defensive shape that stops through balls and protects the space behind.', 'Half pitch, goal with GK; defenders are a back 4 plus one holding midfielder; attackers are 4 midfielders plus 2 forwards, with 2 spare wide players who rotate; GK1 at the halfway end as a target.', 'The game starts with a GK throw to a winger; the attackers try to play round or through the line with movement and runs in behind to score. Defenders keep compact, win the ball and score by passing to the attacking team''s GK.', NULL, NULL, 'Keep distances between players and lines tight while protecting space in behind; delay or force play wide; push up together after a regain.', '6v5 (+GKs)', 13, 15, 'Half pitch', NULL, NULL, 25.0, true, true, true, NULL, 520),
  ('High pressing vs play out and break away', 'defending', 'opposed', 'out_of_possession', 123, 123, 'Session 9: Practice 6', 'Meulensteen (Man Utd)', 'Reading pressing cues, stepping up to press and protecting the space behind.', 'Full pitch with a middle zone marked out; play starts in the high zone with reds building out 7v6.', 'Reds try to play through the press into the middle zone and break away to score. Blues press high together to deny space and block lanes; if the ball goes into the middle zone their defenders step up and press.', NULL, NULL, 'Recognise the cue and press on a negative touch; midfielders press through; the far winger tucks in; defenders push through; far full back covers in behind.', 'Full team units (7v6 in build-up)', NULL, NULL, 'Full pitch', NULL, NULL, 15.0, true, true, true, NULL, 530),
  ('Multi-service receiving, heading and volley warm-up', 'warm_up', 'unopposed', NULL, 125, 125, 'Session 10: Practice 3', 'Meulensteen (Man Utd)', 'Dynamic warm-up with different receiving skills.', 'Area with 5 poles in the centre to weave through and 6 feeders (GKs, coaches or players) next to mannequins around the outside.', 'Inside players weave the poles and go to feeders for 4 actions: return a ground pass; control an aerial ball and volley it back; head it back; receive on the half-turn and pass back.', 'Return 1 touch, volley 2 touches, header 1 touch, half-turn 2 touches.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8.0, false, false, false, NULL, 540),
  ('5v4 possession and immediate transition pressing game', 'rondo', 'overload', 'to_defend', 126, 126, 'Session 10: Practice 4', 'Meulensteen (Man Utd)', 'Pressing as a unit to win the ball and blocking passing lanes.', '15 x 25 yard area split into 2 equal boxes; 2 teams of 5 numbered 1-5.', 'Reds keep it 5v4 in one box against 4 blues while blue 5 waits in the other box; if blues win it they pass to their teammate in the other box and 4 reds go across to press.', 'Reds aim for a set number of passes. Rotate which number waits in the far box.', NULL, 'Press together as a unit; position to block lanes; intercept.', '5v5', 10, 10, '15 x 25 yards', 13.7, 22.9, 6.0, false, false, true, NULL, 550),
  ('5v5 defend to win the ball and counter attack', 'transition', 'opposed', 'to_attack', 127, 127, 'Session 10: Practice 5', 'Meulensteen (Man Utd)', 'Fast counter attacks after winning the ball.', 'Large area with full goals and GKs; all 10 outfield players start in the highlighted zone around the halfway line.', 'Part 1: blues keep possession and attack the GK; when reds win it, all players may move into the attacking half and reds counter fast to score. Part 2: free 5v5 with emphasis on fast counters.', 'Part 1 6 min; Part 2 2 x 4 minute halves.', NULL, 'Counter at once with a forward pass into space; support with forward runs; finish before the opponents recover.', '5v5 (+2 GKs)', 12, 12, NULL, NULL, NULL, 14.0, true, true, true, NULL, 560),
  ('10v10 zonal pressing and transition to attack', 'conditioned_game', 'opposed', 'to_attack', 128, 128, 'Session 10: Practice 6', 'Meulensteen (Man Utd)', 'Defending in zones then reacting instantly to attack after a regain.', 'Pitch split into 3 equal zones with an end goal line and 4 small goals; both teams in 4-3-3.', 'Blues keep possession and, on the coach''s call of ''Attack'', try to score in the 4 small goals. Reds defend locked in zones (3 forwards zone 1, 3 midfielders zone 2, back 4 zone 3); on winning it they are all released and try to dribble over the end goal line, while blues counter-press.', 'Defending reds stay in their zones until they win the ball.', NULL, 'Support with forward runs from different lines while the opponents are out of shape.', '10v10', 20, 20, NULL, NULL, NULL, 10.0, true, false, true, NULL, 570),
  ('Deep block then exploit space behind a high line', 'transition', 'opposed', 'to_attack', 129, 129, 'Session 10: Practice 7', 'Meulensteen (Man Utd)', 'Preparing to defend deep and counter in behind a high, narrow back line (Man City away).', 'Most of a pitch; blues imitate the opponent and attack the reds'' deep compact block (7v6 and 4v4 areas) with a goal and GK; reds have pace up front.', 'The coach passes to the blues who try to play through the deep block and score; when reds win it they look to go early over the top or wide of the high narrow line to score.', NULL, NULL, 'Read the opposition''s shape (high and narrow); play over the top and wide; take the shortest route to goal; supporting runs add options.', NULL, NULL, NULL, NULL, NULL, NULL, 15.0, true, true, true, NULL, 580),
  ('11v11 game in half pitch', 'conditioned_game', 'opposed', NULL, 135, 135, 'Match Day -1: Practice 4', 'Meulensteen (Man Utd)', 'Light, match-realistic tactical stimulus the day before a game.', 'Half-pitch-sized area with goals placed 6 yards outside each box.', '11v11 game with GKs on the shortened pitch.', NULL, NULL, NULL, '11v11 (+GKs)', 22, 22, 'Half pitch', NULL, NULL, 15.0, true, true, true, NULL, 590),
  ('3-ball crossing routine: early crossing zone', 'combination', 'unopposed', 'in_possession', 136, 139, '3-Ball Routine Example 1', 'Meulensteen (Man Utd)', 'Early, low curved deliveries around the defence from the early crossing zone, with timed box runs.', 'Team in positions (full backs, wingers, 3 CMs, 2 forwards) against mannequins as the opposition back and midfield lines; crossing zones (early, main, byline) marked on both flanks; spare players rotate in.', 'Ball 1: Fletcher to Rooney, across to Berbatov, through between the centre backs for Fletcher''s run to shoot. Ball 2: Carrick to Scholes, forward to Giggs who crosses early for 3 runners. Ball 3: coach feeds Evra on the overlap to cross low and hard from the early zone to the near post.', NULL, 'Can be done from either side; mannequin line moves back for crosses from more advanced areas. Leads to the 7v4 conditioned phase of play.', 'Low, hard crosses around the defence; runs to near post, penalty spot and far post.', NULL, NULL, NULL, NULL, NULL, NULL, 8.0, true, true, true, NULL, 600),
  ('3-ball crossing routine: main crossing zone', 'combination', 'unopposed', 'in_possession', 140, 141, '3-Ball Routine Example 2', 'Meulensteen (Man Utd)', 'Floated, precise crosses from the main crossing zone after a switch and full back overlap.', 'Same positional set-up as the 3-ball routine with mannequin lines and marked crossing zones.', 'Ball 1: same central combination ending in Fletcher''s shot. Ball 2: Carrick to Scholes, long switch to Ronaldo, who drives inside and releases Neville on the overlap to cross from the main zone. Ball 3: coach to Rooney, wide for Ronaldo''s run, who floats a cross towards the 6-yard box.', NULL, 'Can be done from either side; leads to the 7v4 conditioned phase of play.', 'Float precise crosses towards the 6-yard area; time runs.', NULL, NULL, NULL, NULL, NULL, NULL, 8.0, true, true, true, NULL, 610),
  ('3-ball crossing routine: byline zone vs 2 defenders', 'combination', 'passive', 'in_possession', 142, 143, '3-Ball Routine Example 3', 'Meulensteen (Man Utd)', 'Driven balls and cut-backs from the byline zone with 2 live centre backs.', 'Same 3-ball set-up but 2 live centre backs replace 2 mannequins.', 'Ball 1: central combination for Fletcher to score. Ball 2: Scholes to Carrick, firm pass to Ronaldo who drives inside and finds Neville overlapping, who cuts back from the byline. Ball 3: coach to Scholes, wide to Giggs who dribbles into the byline zone and drives low across the 6-yard box, cuts back to the penalty spot or chips to the back post.', NULL, 'The 2 live centre backs can also be added to examples 1 and 2.', 'Drive the ball low and hard across the 6-yard box or cut back to the penalty spot.', NULL, NULL, NULL, NULL, NULL, NULL, 8.0, true, true, true, NULL, 620),
  ('7v4 conditioned crossing phase of play', 'phase_of_play', 'overload', 'in_possession', 144, 144, '3-Ball Routine Progression', 'Meulensteen (Man Utd)', 'Delivering many crosses from all six crossing zones against live defenders.', 'Same positional set-up and marked crossing zones, with 4 live defenders replacing the mannequins.', 'After the 3-ball routines the attackers play 7v4, delivering as many crosses as possible from any of the 6 crossing zones using a set number of balls; e.g. through ball for Giggs to cut back from the byline, or Scholes-Carrick switch for Ronaldo and Neville''s overlap with a floated cross.', 'Set number of balls; goals can come from crosses from any of the 6 zones.', '4 active defenders can also replace the mannequins in any of the earlier 3 routines.', NULL, '7v4 +GK', 12, 12, NULL, NULL, NULL, NULL, true, true, true, NULL, 630),
  ('10v10 two-zone possession, attack pole gates', 'positional_game', 'opposed', 'in_possession', 153, 153, 'MD-2 Session (AC Milan): 3', 'Rene Meulensteen (Man Utd)', 'Keep the ball under pressure, then pick the moment to break out and dribble through gates.', 'Full-width area split into two zones, with two pole gates at one end near the box. 10v10.', 'One team defends and squeezes for 4 minutes while the other keeps the ball and looks to dribble through either gate; then roles swap for 4 minutes.', '1-2 touches throughout; score by dribbling through a gate.', NULL, 'Create the opening before attacking a gate; defenders close down quickly together.', '10v10', 20, 20, NULL, NULL, NULL, 8.0, false, false, true, NULL, 640),
  ('10v10 attack the gates then finish', 'small_sided_game', 'opposed', 'in_possession', 154, 154, 'MD-2 Session (AC Milan): 4', 'Rene Meulensteen (Man Utd)', 'Progress through a pole gate and then finish against a goalkeeper.', 'Same set-up as the 2-zone game, but the pole gates move to the edge of the box and a full goal with GK is added.', 'Attackers must dribble through a gate before carrying on to shoot past the GK; teams swap attacking/defending roles after 4 minutes.', 'Must dribble through a gate before a shot can count.', NULL, 'Switch or break lines quickly to open a gate; recognise when to go and drive forward; speed up after the gate before the defence recovers.', '10v10 + GK', 21, 22, NULL, NULL, NULL, 8.0, true, true, true, NULL, 650),
  ('11v11 box to box, use wide areas', 'conditioned_game', 'opposed', 'in_possession', 155, 155, 'MD-2 Session (AC Milan): 5', 'Rene Meulensteen (Man Utd)', 'Play at varied tempos and exploit wide areas with switches while holding team shape.', 'Full pitch with goals on the edge of each penalty box; 11v11 with GKs.', 'Free game with emphasis on changing tempo and switching play to the flanks; team shape kept in and out of possession.', NULL, NULL, 'Switch play; vary tempo; match-specific job such as a wide midfielder marking the opposition playmaker to stop him dictating.', '11v11', 22, 22, 'box to box on a full pitch', NULL, NULL, 12.0, true, true, true, NULL, 660),
  ('11v11 half-pitch game, goals off boxes', 'conditioned_game', 'opposed', NULL, 156, 156, 'MD-1 Session (AC Milan): 4', 'Rene Meulensteen (Man Utd)', 'Sharpness and tactical priming the day before a match.', 'Goals placed 6 yards outside each box so the pitch is roughly half size; 11v11 with GKs.', 'Short, sharp large-sided game.', NULL, NULL, NULL, '11v11 + GKs', 22, 22, 'about half a pitch', NULL, NULL, 15.0, true, true, true, NULL, 670),
  ('9v9 plus joker across pitch width', 'conditioned_game', 'overload', NULL, 159, 159, 'MD-1 Session (AC Milan 2nd leg): 4', 'Rene Meulensteen (Man Utd)', 'Match-eve sharpness game played across the width of the pitch.', '42 x 52 yard area across the pitch width, two goals with GKs, 9v9 plus one neutral.', 'Free game with the neutral playing for the team in possession.', NULL, NULL, NULL, '9v9 (+1) + GKs', 21, 21, '42 x 52 yards', 47.5, 38.4, 15.0, true, true, true, NULL, 680),
  ('10v10+1 possession, press and counter-press', 'possession', 'overload', 'out_of_possession', 163, 164, 'MD-2 Session (Arsenal): 3', 'Rene Meulensteen (Man Utd)', 'Keep the ball under pressure and win it straight back when it is lost.', '50 x 55 yard area, 10v10 plus a joker who plays with the team on the ball.', 'Free keep-ball; on losing it the team presses at once in numbers through midfield to regain it.', NULL, NULL, 'Stay compact; press quickly in transition; defenders read passes, intercept and track runners.', '10v10 (+1)', 21, 21, '50 x 55 yards', 50.3, 45.7, 10.0, false, false, false, NULL, 690),
  ('Midfield block press vs build-up', 'defending', 'overload', 'out_of_possession', 165, 165, 'MD-2 Session (Arsenal): 4', 'Rene Meulensteen (Man Utd)', 'Coordinated midfield-block pressing against a quick combination team.', 'Big area from one goal to an end line beyond halfway, with a pressing line marked; a GK at the goal end plus a second GK; blues have 10 against reds'' outfield block.', 'A GK starts by passing to the blues, who build up and try to dribble over the end line. Reds'' forwards press when the ball reaches the pressing line and midfielders squeeze the next line; if reds win it they pass to either GK to score.', '2 x 4 minute halves. Blues score by dribbling over the end line; reds score by passing to a GK.', NULL, 'Pressure the man on the ball; stay compact and press early in numbers in midfield; read passes and intercept; stay with runners.', '10v10 + 2 GKs', 22, 22, NULL, NULL, NULL, 8.0, false, true, true, NULL, 700),
  ('10v10 attacking patterns into end zone', 'small_sided_game', 'opposed', 'in_possession', 166, 166, 'MD-2 Session (Arsenal): 5', 'Rene Meulensteen (Man Utd)', 'Attack through and around a defence with one-twos, through passes and movement.', 'Main playing zone plus an end zone with mini goals at one end; GKs at both ends; 10v10.', 'A GK starts by passing to a red defender. Reds build up and use combinations and through balls to get a receiver into the end zone, after which everyone is free and they try to score in the mini goals. Blues press, win it and pass to either GK.', 'Reds must get the ball into the end zone with a pass before finishing; blues score by passing to a GK.', NULL, 'Switch quickly side to side through the central midfielders; think and play forward; find players in pockets or forwards dropping off; when a centre back or midfielder is unpressed, look for runs in behind from the far side.', '10v10 + GKs', 22, 22, NULL, NULL, NULL, 12.0, true, true, true, NULL, 710),
  ('11v11+1 positional roles and structure', 'conditioned_game', 'overload', NULL, 167, 167, 'MD-2 Session (Arsenal): 6', 'Rene Meulensteen (Man Utd)', 'Rehearse the game plan, positional roles and team shape at realistic distances.', '11v11 plus a neutral with GKs on three quarters of a pitch.', 'Free game at moderate-to-high intensity, with the coach steering shape: spread wide, play forward quickly, step in to win it, stay compact, runs in behind.', NULL, NULL, 'Keep structure and positional discipline as whole units; play with purpose at match-like intensity; trust decisions under realistic pressure.', '11v11 (+1) + GKs', 23, 23, '3/4 pitch', NULL, NULL, 10.0, true, true, true, NULL, 720),
  ('5v5 quick link-play possession, 1-2 touch', 'possession', 'opposed', 'in_possession', 175, 175, 'MD-3 Session (Chelsea): 3', 'Rene Meulensteen (Man Utd)', 'Controlled possession under pressure with quick link play.', 'Two separate 25 x 25 yard squares, a 5v5 in each.', 'Keep-ball with constant movement and support angles; react fast when the ball is lost or won while keeping shape.', '1-2 touches.', NULL, 'Keep moving; good support angles; fast circulation.', '2 x 5v5', 10, 20, '25 x 25 yards', 22.9, 22.9, 4.0, false, false, false, NULL, 730),
  ('10v10 defensive shape and quick counters', 'transition', 'opposed', 'to_attack', 176, 180, 'MD-3 Session (Chelsea): 4', 'Rene Meulensteen (Man Utd)', 'Defend in shape, press to win the ball, then counter fast using wide players and runs in behind.', 'Large area with a big goal (GK) at the reds'' attacking end; at the other end two central mini goals and wide pole gates.', 'Blues start with the ball and try to score in a mini goal or dribble through a wide pole gate. Reds defend compactly, press to win it, then break with quick interplay, release wingers and finish with low crosses, cut-backs or low shots; blues must then recover quickly.', 'Blue defenders may not defend in the corners once a red has dribbled through a wide pole gate.', 'Repeated on MD-2 (p179). Tweak on MD-2 (p180): blues attack a large goal with a GK on the edge of the box instead of mini goals/gates; reds'' task unchanged.', 'Win it and break quickly; release wide players and make runs in behind; low crosses and cut-backs.', '10v10 (+GKs)', 21, 22, NULL, NULL, NULL, 10.0, true, true, true, NULL, 740),
  ('8v8 defensive shape and quick breaks', 'small_sided_game', 'opposed', 'to_attack', 177, 177, 'MD-3 Session (Chelsea): 5', 'Rene Meulensteen (Man Utd)', 'Apply the session''s defending and counter-attacking principles in a freer game.', '8v8 with a large goal and GK at one end and two small goals at the other.', 'Reds defend compactly, press together and break quickly on regaining; in possession they build calmly, link quickly, get wide early and run in behind the striker, finishing from low crosses or cut-backs. Blues attack the small goals.', NULL, NULL, 'Stay organised and compact and press as a unit; win it and break with quick support runs; attack the final third with low crosses and cut-backs.', '8v8 + GK', 17, 17, NULL, NULL, NULL, 8.0, true, true, true, NULL, 750),
  ('Back four press, cover, screen passes', 'defending', 'opposed', 'out_of_possession', 181, 181, 'MD-2 Session (Chelsea): 5', 'Rene Meulensteen (Man Utd)', 'Defenders step in at the right moment to get tight and stop attackers turning.', 'Area in front of the box and goal with GK; red back four plus a holding midfielder screening; blue attackers (two midfielders, two wingers, a striker) with the coach acting as an extra central midfielder feeding passes.', 'Coach and midfield partner feed passes into the blue attackers, who try to turn, combine, get in behind and score. The holding midfielder screens and intercepts; the back four stay compact and step in early to stop the turn.', NULL, NULL, 'Get on top of your man; compact press and cover; screen and intercept; repeat for correct starting positions and timing.', '5 attackers + coach v 4+1 + GK', 12, 13, NULL, NULL, NULL, 10.0, true, true, true, NULL, 760),
  ('Three-part attacking combinations to goal', 'combination', 'unopposed', 'in_possession', 182, 184, 'MD-2 Session (Chelsea): 6', 'Rene Meulensteen (Man Utd)', 'Rehearse counter-attack, wide-attack and central-shot patterns with set roles and rotations.', 'Half pitch to a goal with GK; front unit of a holding midfielder, two central midfielders, two wingers and a striker; balls with the coach.', 'Part 1: counter-attack combinations unopposed except for the GK. Part 2: GK plays to the holding midfielder, then the midfielders, wingers and striker attack wide with combination play, crosses and box runs. Part 3: short, quick combinations in the centre to open space for a shot from a marked shooting zone outside the box.', NULL, 'After the unopposed run, a back four plus GK defend while 5 attackers try to score (Parts 2 and 3).', 'Move by role and rotation in each pattern; correct timing and support movement; keep tempo and accuracy to the final action.', '6 attackers + GK, then 5 v 4 + GK', 7, 12, 'half pitch', NULL, NULL, 10.0, true, true, true, NULL, 770),
  ('Phase of play: width vs narrow diamond', 'phase_of_play', 'passive', 'in_possession', 191, 191, 'Chapter 8: Practice 1', 'Rene Meulensteen (Man Utd)', 'Combine centrally to draw a narrow diamond midfield, then release the full back and attack the box from wide.', 'Half pitch to a goal with GK; centre backs, three rotating central midfielders, full backs, wingers and forwards attack; two passive defenders guard the box; a cone diamond marks the opponent''s midfield.', 'Ball circulates centrally from the centre backs before being released to a full back on the run; the move ends with a cross and coordinated box runs. GK restarts by throwing or kicking to the start.', 'Central players rotate roles each phase (two as centre backs, three as midfielders, one resting).', NULL, 'Combine centrally before going wide; time the pass so the full back receives in space on the run; coordinated near post, far post and edge-of-box runs.', 'attacking unit v 2 passive defenders + GK', NULL, NULL, 'half pitch', NULL, NULL, 8.0, true, true, true, NULL, 780),
  ('8v8 exploit width vs narrow diamond', 'small_sided_game', 'opposed', 'in_possession', 192, 192, 'Chapter 8: Practice 2', 'Rene Meulensteen (Man Utd)', 'Break a narrow diamond midfield by playing through the centre then out wide early.', 'Pitch with wide channels marked down both sides; 8v8 plus GKs, each team with two players in the wide zones.', 'Part 1 (6 min): conditioned game. Shots from the central area must come from behind halfway; once over halfway the team must use its unmarked wide players to deliver a cross. Part 2 (10 min): normal 8v8 + GKs without zones but with the same aims.', 'Central shots only from behind the halfway line; over halfway, attacks finish through the wide players.', 'Part 2 removes the wide zones.', 'Good central combinations to get past halfway; then go wide as early as possible; forward runs to finish.', '8v8 + GKs', 18, 18, NULL, NULL, NULL, 16.0, true, true, true, NULL, 790),
  ('Break a narrow block with switches, crosses', 'phase_of_play', 'opposed', 'in_possession', 193, 193, 'Chapter 8: Practice 3', 'Rene Meulensteen (Man Utd)', 'Stretch and break down a compact, narrow defensive block with switches and crosses.', '11v11 on half a pitch; defending team stays compact and narrow in front of and within the box width (zone marked), attackers have wide channels.', 'Part 1 (10 min): attack v defence, reds move the ball quickly to shift the block, switch play, get wide and cross with timed box runs. Part 2 (10 min): free 11v11 with the same emphasis.', NULL, 'Part 2: free 11v11 game.', 'Hold an attacking shape that stretches the block; move the ball fast and switch before crossing; varied box runs (near post, far post, edge).', '11v11', 22, 22, 'half a pitch', NULL, NULL, 20.0, true, true, true, NULL, 800),
  ('10v10 switch play to wide zones', 'small_sided_game', 'opposed', 'in_possession', 194, 194, 'Chapter 8: Practice 4', 'Rene Meulensteen (Man Utd)', 'Quick circulation and switches to exploit wide areas against a compact block.', '10v10 with two clear wide zones that only the reds'' wide players may enter; reds attack two small goals, blues counter to a large goal with GK.', 'Reds build up in their own half 7v3, then meet a compact 4-1-4-1 block in the attacking half and look to switch into the wide zones and score. If blues win the ball they counter into the large goal with no zone limits.', 'Only reds'' wide players operate in the wide zones; blues free on the counter.', NULL, 'Quick combinations only in the centre; play forward early; switch to the wide zones and attack the goals.', '10v10 + GK', 21, 21, NULL, NULL, NULL, 12.0, true, true, true, NULL, 810),
  ('11v11 play wide early, cross into box', 'conditioned_game', 'opposed', 'in_possession', 195, 195, 'Chapter 8: Practice 5', 'Rene Meulensteen (Man Utd)', 'Break a compact 4-1-4-1 using width, switches and early crosses.', 'Full pitch, 11v11; marked crossing zones wide of the box and a shooting zone in it; defending team set up in a compact 4-1-4-1 centrally.', 'Part 1 (8 min): reds circulate, play wide early and use the crossing and shooting zones. Part 2 (10 min): 11v11 on half a pitch, 2 x 5 minutes.', NULL, 'Part 2: 11v11 on half a pitch.', 'Move the ball quickly or switch to shift the block; wide players early for crosses; timed box runs, no offsides, attack near post, far post and edge.', '11v11', 22, 22, 'full pitch, then half pitch', NULL, NULL, 18.0, true, true, true, NULL, 820),
  ('Central and wide overloads vs compact defence', 'conditioned_game', 'overload', 'in_possession', 196, 196, 'Chapter 8: Practice 6', 'Rene Meulensteen (Man Utd)', 'Find central (6v4) and wide (2v1) attacking solutions against a compact defence.', 'Pitch with wide zones on both flanks; GK starts each attack; central overload 6v4, wide 2v1 with one blue defender who may step out.', 'GK serves to a central midfielder or a wide player. If it goes central, attack 6v4 through the middle; if it goes wide, the two wide reds combine 2v1 to cross while the others support and make box runs without entering the wide zones.', 'Three wide players per side rotating (one attacks, one supports, one rests); central players outside the wide zones; two extra central players rotate.', NULL, 'Attack quickly and decisively with the numerical advantage; fast combinations; coordinated box runs.', '6v4 central, 2v1 wide + GK', NULL, NULL, NULL, NULL, NULL, 30.0, true, true, true, NULL, 830)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'ren-meulensteen-man-utd-methods-of-success-vol-2-full-season-plan-training-sessi') b;
